(() => {
  const encoder=new TextEncoder(),A=window.DEMO,xml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'})[c]);
  const table=Array.from({length:256},(_,n)=>{for(let i=0;i<8;i++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
  function crc(bytes){let c=0xffffffff;for(const b of bytes)c=table[(c^b)&255]^(c>>>8);return (c^0xffffffff)>>>0;}
  function zip(files){const chunks=[],central=[];let offset=0,size=0;for(const [name,input] of files){const data=typeof input==='string'?encoder.encode(input):input,n=encoder.encode(name),checksum=crc(data),h=new Uint8Array(30+n.length),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,checksum,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,n.length,true);h.set(n,30);chunks.push(h,data);const c=new Uint8Array(46+n.length),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,checksum,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,n.length,true);cv.setUint32(42,offset,true);c.set(n,46);central.push(c);size+=c.length;offset+=h.length+data.length;}const e=new Uint8Array(22),v=new DataView(e.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,files.length,true);v.setUint16(10,files.length,true);v.setUint32(12,size,true);v.setUint32(16,offset,true);return new Blob([...chunks,...central,e],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});}
  const paragraph=(text,style='Normal')=>'<w:p><w:pPr><w:pStyle w:val="'+style+'"/></w:pPr><w:r><w:t xml:space="preserve">'+xml(text)+'</w:t></w:r></w:p>';
  const heading=text=>paragraph(text,'Heading1');
  function drawing(id,w,h){return '<w:p><w:pPr><w:keepNext/></w:pPr><w:r><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="'+w+'" cy="'+h+'"/><wp:docPr id="'+id+'" name="Evidence '+id+'"/><a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:nvPicPr><pic:cNvPr id="'+id+'" name="Evidence"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="rImg'+id+'"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="'+w+'" cy="'+h+'"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>';}
  async function makeReport(week){
    const s=A.read(),rows=A.weekTasks(week),next=A.weekTasks(week+1),from=Date.UTC(2026,0,5)+(week-1)*7*86400000,to=from+6*86400000,fmt=ms=>new Date(ms).toISOString().slice(0,10),files=[],rels=[];let imageId=0;
    let body=paragraph('SAMPLE PROJECT / DEMO','Subtitle')+paragraph('가상 현장 A 제'+week+'주 주간 공사 보고서','Title')+paragraph(fmt(from)+' ~ '+fmt(to))+paragraph('이번 주 간트 '+rows.length+'개 작업 · 본사 검토 결과와 현장 제출 증빙')+paragraph('프로토타입 시연 자료 · 실제 현장 기록이 아닙니다.','Caption');
    async function photo(url,caption,width=4700000){const response=await fetch(url);if(!response.ok)throw Error('보고서 사진을 불러오지 못했습니다.');const bytes=new Uint8Array(await response.arrayBuffer()),blob=new Blob([bytes]),bitmap=await createImageBitmap(blob);const w=width,h=Math.round(w*bitmap.height/bitmap.width);bitmap.close();const id=++imageId;const ext=url.endsWith('.png')?'png':'jpg';files.push(['word/media/photo'+id+'.'+ext,bytes]);rels.push('<Relationship Id="rImg'+id+'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/photo'+id+'.'+ext+'"/>');return drawing(id,w,h)+paragraph(caption,'Caption');}
    body+=heading('1. 이번 주 작업별 진행 현황');
    for(const t of rows){const rev=s.reviews[t.id],sub=s.submissions.filter(x=>x.taskId===t.id).at(-1),e=s.extensions[t.id];body+=paragraph(t.name+' · ID '+t.id,'Heading2')+paragraph('계획 '+t.start+' ~ '+t.originalFinish+(e?.state==='approved'?' / 변경 종료 '+e.end+' · 지연·이월':''))+paragraph('작업 분류: '+A.categories[A.category(t)]+' / 검토 상태: '+(A.labels[rev?.state]||'증빙 대기'));
      if(Date.parse(t.actualStart||t.start)<from)body+=paragraph('지난주 내용: 이전 주부터 이어진 작업입니다. '+(s.submissions.filter(x=>x.taskId===t.id&&Date.parse(x.at)<from).length?'이전 제출 기록을 기준으로 비교합니다.':'지난주 제출 사진·공정률은 아직 연결되지 않았습니다.'));
      if(t.id==='45'){body+=paragraph('이번 주 AI 관측: 왼쪽 벽 W01 78.50%, 오른쪽 벽 W02 82.00%. 설치 ÷ (설치 + 미설치), 인식 불가 제외. 관측 수락과 작업 완료 확인을 구분합니다.');body+=await photo(window.DEMO_DATA.photos.wallAfter,'02.20 원본 · AI 분석 전');body+=await photo(window.DEMO_DATA.photos.wallOverlay,'02.20 같은 사진 · AI 분석 표시');}
      else if(sub){body+=paragraph('이번 주 보고: '+sub.report);if(t.id==='40')body+=await photo(window.DEMO_DATA.photos.counterBefore,'02.15 착수 전 참고 · 생성 예시');body+=await photo(sub.photo,t.id==='40'?'02.18 골조 설치 후 · 생성 예시':'최신 제출 증빙 · '+sub.attempt+'차');if(rev?.reason)body+=paragraph('반려 사유 이력: '+rev.reason);}
      else body+=paragraph('이번 주 보고: 증빙 제출 대기. 사진이나 공정률 자료가 연결되지 않았습니다.');
    }
    body+=heading('2. 지연·추가 기간 요청');const extensions=Object.entries(s.extensions).filter(([id])=>rows.some(t=>t.id===id));if(!extensions.length)body+=paragraph('해당 주차 추가 기간 요청 없음');for(const [id,e] of extensions){const t=A.effectiveTasks().find(t=>t.id===id);body+=paragraph(t.name+' · ID '+id,'Heading2')+paragraph('기존 종료일 '+e.original+' → 요청 종료일 '+e.end)+paragraph('요청 사유: '+e.reason)+paragraph('본사 검토: '+({pending:'검토 대기',approved:'수락 · 원래 일정을 남기고 지연·이월',rejected:'반려'}[e.state]));if(e.reviewReason)body+=paragraph('반려 사유: '+e.reviewReason);}
    body+=heading('3. 다음 주 간트 작업');if(!next.length)body+=paragraph('다음 주 예정 작업 없음');for(const t of next)body+=paragraph('• '+t.name+' · ID '+t.id+' / '+t.start+' ~ '+t.finish+(s.extensions[t.id]?.state==='approved'?' / 지연·이월 · 원래 종료 '+t.originalFinish:''));
    body+=heading('4. 본사 검토 이력');const events=s.events.filter(e=>rows.some(t=>t.id===e.taskId));if(!events.length)body+=paragraph('초기 시연 상태입니다.');events.forEach(e=>body+=paragraph('ID '+e.taskId+' · '+e.action+(e.reason?' / '+e.reason:'')));
    body+=heading('5. 웹에서 사진과 검토 이력 확인')+paragraph('QR을 스캔하면 DEMO 시연 사이트로 연결됩니다.').replace('</w:pPr>','<w:keepNext/></w:pPr>');body+=await photo('assets/site-qr.png','링크가 있으면 누구나 시연 화면을 볼 수 있습니다.',1200000);body+=paragraph('https://example.com/');
    const header='<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';files.push(['word/document.xml',header+'<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing"><w:body>'+body+'<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1000" w:bottom="1000" w:left="1100" w:right="1100"/></w:sectPr></w:body></w:document>']);
    files.push(['[Content_Types].xml',header+'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="jpg" ContentType="image/jpeg"/><Default Extension="png" ContentType="image/png"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/></Types>']);
    files.push(['_rels/.rels',header+'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rOffice" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>']);
    files.push(['word/_rels/document.xml.rels',header+'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>'+rels.join('')+'</Relationships>']);
    files.push(['word/styles.xml',header+'<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Arial" w:eastAsia="맑은 고딕"/><w:sz w:val="21"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:spacing w:after="100" w:line="290" w:lineRule="auto"/></w:pPr></w:pPrDefault></w:docDefaults><w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/></w:style><w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:pPr><w:spacing w:before="150" w:after="240"/></w:pPr><w:rPr><w:b/><w:sz w:val="38"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Subtitle"><w:name w:val="Subtitle"/><w:rPr><w:color w:val="888888"/><w:sz w:val="18"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading1"><w:name w:val="heading 1"/><w:pPr><w:keepNext/><w:spacing w:before="330" w:after="180"/></w:pPr><w:rPr><w:b/><w:sz w:val="28"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Heading2"><w:name w:val="heading 2"/><w:pPr><w:keepNext/><w:spacing w:before="230" w:after="130"/></w:pPr><w:rPr><w:b/><w:sz w:val="23"/></w:rPr></w:style><w:style w:type="paragraph" w:styleId="Caption"><w:name w:val="Caption"/><w:rPr><w:color w:val="888888"/><w:sz w:val="17"/></w:rPr></w:style></w:styles>']);
    return zip(files);
  }
  let busy=false;
  window.downloadWeeklyReport=async value=>{if(busy)return;const week=Math.max(1,Math.min(16,Number(value)||7));busy=true;try{window.DemoUI.toast('현재 검토 결과를 담아 Word 보고서를 만듭니다.');const blob=await makeReport(week),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ALO_Site A_W'+String(week).padStart(2,'0')+'.docx';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);window.DemoUI.toast('제'+week+'주 Word 보고서를 내려받았습니다.');}catch(e){window.DemoUI.toast('보고서 생성 실패: '+e.message);}finally{busy=false;}};
})();
